18	
19	func pollPage(t *testing.T, h http.Handler, url string) (*httptest.ResponseRecorder, map[string]any) {
20		t.Helper()
21		return doRequest(t, h, http.MethodGet, url)
22	}
23	
24	func TestPollReturnsExistingPage(t *testing.T) {
25		h, _ := newTestHandler(t)
26		seedDoc(t, h, "doc", 3)
27	
28		w, body := pollPage(t, h, "/v1/documents/doc/changes/poll?after=1&limit=2&waitMs=1000")
29		if w.Code != 200 {
30			t.Fatalf("status = %d body = %s", w.Code, w.Body.String())
31		}
32		rows := body["changes"].([]any)
33		if len(rows) != 2 || body["nextCursor"].(float64) != 3 || body["timedOut"] != false {
34			t.Fatalf("page = %v", body)
35		}
36	}
37	
38	func TestPollUnknownDocumentImmediateEmpty(t *testing.T) {
39		h, _ := newTestHandler(t)
40	
41		done := make(chan struct {
42			code int
43			body map[string]any
44		}, 1)
45		go func() {
46			w, body := pollPage(t, h, "/v1/documents/ghost/changes/poll?waitMs=30000")
47			done <- struct {
48				code int
49				body map[string]any
50			}{w.Code, body}
51		}()
52		select {
53		case r := <-done:
54			if r.code != 200 {
55				t.Fatalf("status = %d", r.code)
56			}
57			if len(r.body["changes"].([]any)) != 0 || r.body["nextCursor"].(float64) != 0 || r.body["timedOut"] != false {
58				t.Fatalf("unknown doc page = %v", r.body)
59			}
60		case <-time.After(2 * time.Second):
61			t.Fatal("unknown document parked the poll")
