565		if r["created"] != false || r["cursor"].(float64) != 1 {
566			t.Fatalf("post-restart result = %v", r)
567		}
568	
569		// A poll parked on the restarted store times out at the same cursor.
570		w, body = doRequest(t, h2, http.MethodGet, "/v1/documents/doc/changes/poll?after=1&waitMs=20")
571		if w.Code != 200 || body["timedOut"] != true || body["nextCursor"].(float64) != 1 {
572			t.Fatalf("poll after restart = %d %v", w.Code, body)
573		}
574	}
