490		// Idempotency survives the restart: same session device and decoded
491		// payload -> created=false with the first cursor.
492		w, body := postSessionChanges(t, h2, "sess", "doc1", `{"changes":[{"id":"c1","payload":{"a":1}}]}`)
493		if w.Code != http.StatusOK {
494			t.Fatal(w.Body.String())
495		}
496		r := body["results"].([]any)[0].(map[string]any)
497		if r["created"] != false || r["cursor"].(float64) != 1 {
498			t.Fatalf("idempotent after restart = %v", r)
499		}
500	
501		// So does the conflict decision.
502		w, body = postSessionChanges(t, h2, "sess", "doc1", `{"changes":[{"id":"c1","payload":{"a":2}}]}`)
503		if w.Code != http.StatusConflict || body["conflictId"] != "c1" {
504			t.Fatalf("conflict after restart = %d %s", w.Code, w.Body.String())
505		}
506	
507		// Raw payloads read back verbatim and the cursor space continues.
508		w, body = doRequest(t, h2, http.MethodGet, "/v1/documents/doc1/changes")
509		if w.Code != http.StatusOK {
510			t.Fatal(w.Body.String())
511		}
512		rows := body["changes"].([]any)
513		if len(rows) != 2 || body["nextCursor"].(float64) != 2 {
514			t.Fatalf("list after restart = %v next=%v", rows, body["nextCursor"])
515		}
516		second := rows[1].(map[string]any)
517		if second["deviceId"] != "dev" {
518			t.Fatalf("device after restart = %v", second)
519		}
520		payload := second["payload"].([]any)
521		if len(payload) != 3 || payload[0].(float64) != 1 || payload[1] != true || payload[2] != nil {
522			t.Fatalf("payload after restart = %v", second["payload"])
523		}
524	
525		w, body = postSessionChanges(t, h2, "sess", "doc1", `{"changes":[{"id":"c3","payload":42}]}`)
526		if w.Code != http.StatusOK {
527			t.Fatal(w.Body.String())
528		}
529		r = body["results"].([]any)[0].(map[string]any)
530		if r["created"] != true || r["cursor"].(float64) != 3 {
531			t.Fatalf("post-restart cursor = %v", r)
532		}
533	}
534	
535	// A compacted-away id still answers idempotency and conflict decisions from
536	// its retained summary when the commit arrives through the session path.
537	func TestSessionPostChangesHTTPCompactedIdentity(t *testing.T) {
538		h, _ := newTestHandler(t)
539		createSessionViaHTTP(t, h, "dev", "sess")
540		postDocChanges(t, h, "doc", "dev", 2)
541		w, _ := postJSON(t, h, "/v1/documents/doc/snapshots", map[string]any{"cursor": 2, "state": map[string]any{"s": 1}})
542		if w.Code != http.StatusOK {
543			t.Fatal(w.Body.String())
544		}
545		if w := compactChanges(t, h, "doc", "dev"); w.Code != http.StatusOK {
546			t.Fatalf("compact = %d %s", w.Code, w.Body.String())
547		}
548	
549		// The trimmed id is idempotent with its first cursor.
550		w, body := postSessionChanges(t, h, "sess", "doc", `{"changes":[{"id":"c1","payload":{"n":1}}]}`)
551		if w.Code != http.StatusOK {
552			t.Fatalf("trimmed idempotent = %d %s", w.Code, w.Body.String())
553		}
554		r := body["results"].([]any)[0].(map[string]any)
555		if r["created"] != false || r["cursor"].(float64) != 1 {
556			t.Fatalf("trimmed result = %v", r)
557		}
558	
559		// A differing payload against the trimmed id is still a 409.
560		w, body = postSessionChanges(t, h, "sess", "doc", `{"changes":[{"id":"c1","payload":{"n":9}}]}`)
561		if w.Code != http.StatusConflict || body["conflictId"] != "c1" {
562			t.Fatalf("trimmed conflict = %d %s", w.Code, w.Body.String())
563		}
564	
565		// New ids continue past the pre-compaction cursor space.
566		w, body = postSessionChanges(t, h, "sess", "doc", `{"changes":[{"id":"c3","payload":{"n":3}}]}`)
567		if w.Code != http.StatusOK {
568			t.Fatal(w.Body.String())
569		}
570		r = body["results"].([]any)[0].(map[string]any)
571		if r["created"] != true || r["cursor"].(float64) != 3 {
572			t.Fatalf("post-compaction cursor = %v", r)
573		}
574	}
575	
576	// The document-level commit is untouched by the new entry: it still requires
577	// its body deviceId and answers with its own shapes.
578	func TestSessionPostChangesHTTPDocumentPostUnchanged(t *testing.T) {
579		h, _ := newTestHandler(t)
580		createSessionViaHTTP(t, h, "dev", "sess")
581	
582		w, _ := postJSON(t, h, "/v1/documents/doc1/changes", `{"changes":[{"id":"a","payload":1}]}`)
583		if w.Code != http.StatusBadRequest {
