373	func TestReplayConcurrentCursorsContiguous(t *testing.T) {
374		s, _ := app.Open("")
375		defer func() { _ = s.Close() }()
376		if _, err := s.RegisterDevice("dev"); err != nil {
377			t.Fatal(err)
378		}
379	
380		const writers = 20
381		const perWriter = 5
382		var wg sync.WaitGroup
383		errs := make(chan error, writers)
384		for w := 0; w < writers; w++ {
385			wg.Add(1)
386			go func(w int) {
387				defer wg.Done()
388				ops := make([]events.Change, 0, perWriter)
389				for i := 0; i < perWriter; i++ {
390					ops = append(ops, events.Change{
391						ID:       fmt.Sprintf("w%02d-o%02d", w, i),
392						DeviceID: "dev",
393						Payload:  json.RawMessage(fmt.Sprintf(`{"w":%d,"i":%d}`, w, i)),
394					})
395				}
396				if _, err := s.ReplayChanges("doc", ops); err != nil {
397					errs <- err
398				}
399			}(w)
400		}
401		wg.Wait()
402		close(errs)
403		for err := range errs {
404			t.Fatal(err)
405		}
406	
407		rows, next, err := s.ListChanges("doc", 0, 1000)
408		if err != nil {
409			t.Fatal(err)
410		}
411		if len(rows) != writers*perWriter || next != int64(writers*perWriter) {
412			t.Fatalf("rows=%d next=%d, want %d/%d", len(rows), next, writers*perWriter, writers*perWriter)
413		}
414		seenCursors := make(map[int64]bool, len(rows))
415		for _, r := range rows {
416			if seenCursors[r.Cursor] {
417				t.Fatalf("cursor %d allocated twice", r.Cursor)
418			}
419			seenCursors[r.Cursor] = true
420		}
421		for c := int64(1); c <= next; c++ {
422			if !seenCursors[c] {
423				t.Fatalf("cursor %d missing from the contiguous range", c)
424			}
425		}
426	}
